struct alignas(2) A { char id = 1; constexpr int get(A*) const { return 1; } };
struct alignas(8) B { char id = 2; constexpr int get(B*) const { return 2; } };
struct alignas(4) C { char id = 3; constexpr int get(C*) const { return 3; } };
template <class... U> struct List {};
template <class... U> constexpr int length(List<U...>) { return sizeof...(U); }
template <class... U> constexpr int count(U...) { return sizeof...(U); }
template <class... U> constexpr decltype(sizeof 0) strictest() { decltype(sizeof 0) m = 1; ((m = alignof(U) > m ? alignof(U) : m), ...); return m; }
